DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT116-S3-Q6$batch07$ AND q.stimulus=$batch07$Antonia: The stock market is the best place to invest your money these days; although it is often volatile, it provides the opportunity to make a large profit quickly. Maria: I agree that the stock market provides the opportunity to make large profits quickly, but one is just as likely to take a huge loss. I think it is better to invest in savings bonds, which provide a constant, reliable income over many years.$batch07$ AND q.prompt=$batch07$Antonia's and Maria's statements provide the most support for holding that they disagree about whether$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch07$a34f24a2-710f-4c34-89c5-6550494f64a2$batch07$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch07$a34f24a2-710f-4c34-89c5-6550494f64a2$batch07$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT116-S3-Q6'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch07$Antonia's Position$batch07$, $batch07$The stock market is the best place to invest. It is volatile, but it gives you a shot at a large, quick profit.$batch07$), (1, $batch07$Maria's Position$batch07$, $batch07$Yes, you can make a large profit quickly, but you are just as likely to take a huge loss. Savings bonds are better, because they pay a constant, reliable income.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Look at what Maria concedes. Maria agrees about the quick profits, and Antonia already admitted the volatility. So the facts are shared. What they disagree about is the tradeoff: Antonia picks the big upside despite the risk; Maria picks the steady income. Antonia never mentions "reliable income" by name, but calling the volatile market the *best* place to invest puts Antonia on the other side of that choice.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether a reliable income is better than a risky chance at a fast, large profit.$batch07$)) v(position,label,body) WHERE e.id=$batch07$a34f24a2-710f-4c34-89c5-6550494f64a2$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
